-- Import all supplied Community Relations workbooks.
-- Covers May-Dec 2025 and Jan-Aug 2026. Safe to rerun.
insert into public.reporting_periods (period_date)
select v::date from (values
  ('2025-05-01'),('2025-06-01'),('2025-07-01'),('2025-08-01'),('2025-09-01'),('2025-10-01'),('2025-11-01'),('2025-12-01'),
  ('2026-01-01'),('2026-02-01'),('2026-03-01'),('2026-04-01'),('2026-05-01'),('2026-06-01'),('2026-07-01'),('2026-08-01')
) x(v) on conflict (period_date) do nothing;

insert into public.monthly_submissions (reporting_period_id, department_id)
select p.id, d.id from public.reporting_periods p cross join public.departments d
where p.period_date between '2025-05-01' and '2026-08-01'
on conflict (reporting_period_id, department_id) do nothing;

insert into public.report_section_status (reporting_period_id, report_section_id)
select p.id, s.id from public.reporting_periods p cross join public.report_sections s
where p.period_date between '2025-05-01' and '2026-08-01' and s.is_active
on conflict (reporting_period_id, report_section_id) do nothing;

insert into public.csr_monthly_reports (reporting_period_id, social_infrastructure_projects, other_activities)
select p.id, v.projects::jsonb, v.others::jsonb
from public.reporting_periods p
join (values
 ('2025-05-01','{"html":"<p>Community Investment Projects: Fier municipality project started implementation; Roskovec municipality working to select contractor and submit its documentation.</p>"}','{"html":"<ul><li>Conducting Social Risk Assessment for the new wells to be drilled as part of Drilling schedule for 2025.</li><li>Visiting drilling site locations and providing social inputs.</li><li>Received a request from Fier Hospital to support with medical equipment. Request approved internally and equipment to be delivered in June 2025.</li><li>Regular communication with local authorities and residents to address concerns related to operations at pad M37a.</li><li>Received a request from Mbrostar Administrative Unit to support with improvement of agriculture roads in the area. Cost estimate to be prepared prior decision making.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2025-06-01','{"html":"<p>Community Investment Projects: Fier municipality project has been finalized; Roskovec municipality selected contractor and submitted its documentation. Request sent to national authorities to extend deadline of project implementation.</p>"}','{"html":"<ul><li>Conducting Social Risk Assessment for the new wells to be drilled as part of Drilling schedule for 2025.</li><li>Visiting drilling site locations and providing social inputs.</li><li>Delivered medical equipment to Fier hospital as per their request.</li><li>Regular communication with local authorities and residents to address concerns related to operations at pad M37a.</li><li>Submitted for the approval of national authorities the request from Mbrostar Administrative Unit to support with improvement of agriculture roads in the area.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2025-07-01','{"html":"<p>Community Investment Projects: Obtained approval from MIE about extension of Roskovec municipality project deadline. Started contracting procedures.</p>"}','{"html":"<ul><li>Regular communication with local authorities and residents to address concerns related to operations at pad M37a.</li><li>Requests to cut bushes at wells 583M, 1754P and 1517S.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2025-08-01','{"html":"<p>Community Investment Projects: Contract for Roskovec municipality project signed and construction works due to start soon.</p>"}','{"html":"<ul><li>Regular communication with local authorities and residents to address concerns related to operations at pad M37a.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2025-09-01','{"html":"<p>Community Investment Projects: Roskovec municipality project started implementation and is being supervised by Bankers Construction Team.</p>"}','{"html":"<ul><li>Letter received from Patos municipality about sludge waste at well M7-S. Being discussed internally.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2025-10-01','{"html":"<p>Community Investment Projects: Roskovec municipality project started implementation and is being supervised by Bankers Construction Team.</p>"}','{"html":"<ul><li>Received a request from Patos Pre-University Education Office to support with materials for day-to-day activities. Request has been approved and working with Procurement to purchase the materials.</li><li>Letter received from Patos municipality about sludge waste at well M7-S. Request was approved and cleaning works finalized.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2025-11-01','{"html":"<p>Community Investment Projects: Roskovec municipality project is being implemented as planned and being supervised by Bankers Construction Team.</p>"}','{"html":"<ul><li>Patos Pre-University Education Office request: Working with Procurement to purchase the requested materials.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2025-12-01','{"html":"<p>Community Investment Projects: Roskovec municipality project has been finalized. Municipality is working to prepare final documentation.</p>"}','{"html":"<ul><li>Patos Pre-University Education Office request: Materials delivered as per the request.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2026-01-01','{"html":"<p>Community Investment Projects: Working with local municipalities to prepare and submit documentation for 2026 community investment projects.</p>"}','{"html":"<ul><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2026-02-01','{"html":"<p>Community Investment Projects: Patos municipality was submitted and internally approved; Roskovec municipality project is being reviewed internally prior submission for national authorities approval.</p>"}','{"html":"<ul><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li><li>Fier Hospital sent a request for support with materials for neonatal department. Due to company situation the request will not be supported.</li><li>Patos municipality request to install/clean culverts at pads J29a, I27a, and wells 1819S and 1536S to improve drainage and prevent flooding. Request was approved and works have started.</li><li>Mbrostar Administrative Unit sent a request to dispose the soil excavated from cleaning drainage canals in Kallm I Madh. Request was not approved.</li></ul>"}'),
 ('2026-03-01','{"html":"<p>Community Investment Projects: Roskovec municipality project was approved internally. Waiting for Fier municipality to submit 2026 community investment project.</p>"}','{"html":"<ul><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260. Waiting for Fier municipality to submit the 2026 community investment project.</li><li>Works for installation and cleaning of culverts at pads J29a, I27a, and wells 1819S and 1536S have been finalized.</li><li>Request from Fier municipality to support ANTIK association in the organization of international project Apollo Art Colony 2026. Being discussed internally.</li></ul>"}'),
 ('2026-04-01','{"html":"<p>Community Investment Projects: Met with Administrator of Mbrostar Administrative Unit to discuss potential community investment projects to be submitted. Explained procedures and steps to be followed.</p>"}','{"html":"<ul><li>Request from Fier municipality to support ANTIK association in the organization of international project Apollo Art Colony 2026 not approved due to company financial situation.</li><li>Request from Vlora municipality to support with cleaning of a drainage canal in Vlora area. Request not supported given company financial situation.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2026-05-01','{"html":"<p>Community Investment Projects: Prepared documentation and submitted for approval of national authorities Patos and Roskovec municipality 2026 community investment projects.</p>"}','{"html":"<ul><li>Together with Audit department prepared and submitted for approval a letter about impact mitigation expenses.</li><li>Received a request from Patos municipality to support with cleaning of water pump irrigation basement to help Belina farmers. Request approved and cleaning works finalized.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2026-06-01','{"html":"<p>Community Investment Projects: Prepared and submitted a letter to national authorities for approval of Patos and Roskovec municipality 2026 community investment projects as per Article 27 of the PA.</p>"}','{"html":"<ul><li>Received a request from Fier prison to support with chairs for their offices. Working to purchase the requested materials.</li><li>Received a request from Roskovec Fire protection department to support with materials and equipment. Being discussed internally.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2026-07-01','{"html":"<p>Community Investment Projects: Received approval from MIE for Roskovec and Patos municipalities projects. Started contracting procedures for Patos; waiting for contractor documentation for Roskovec.</p>"}','{"html":"<ul><li>Fier Prison request: Delivered 20 office chairs as per the request.</li><li>Roskovec Fire Protection Department request: Obtained approval to support with materials and working to purchase them.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}'),
 ('2026-08-01','{"html":"<p>Community Investment Projects: Contract for Patos municipality project was finalized and is to be signed; waiting for Roskovec municipality to select contractor and submit documentation; Fier municipality project submitted for national authority approval.</p>"}','{"html":"<ul><li>Roskovec Fire Protection department request: Working with SCM to purchase flashlights and radios.</li><li>L26a: Regular monitoring of the pad due to complaints from Belina residents on gas smell related to operations at well 5260.</li></ul>"}')
) v(period_date, projects, others) on p.period_date = v.period_date::date
on conflict (reporting_period_id) do update set social_infrastructure_projects = excluded.social_infrastructure_projects, other_activities = excluded.other_activities, updated_at = now();

insert into public.csr_grievances (reporting_period_id, grievance_date, project_activity, category, status, validity)
select p.id, v.grievance_date::date, v.project_activity, v.category, v.status, v.validity::public.grievance_validity
from public.reporting_periods p join (values
 ('2025-05-01','2025-05-06','Drilling','Noise','Closed','VALID'),('2025-05-01','2025-05-23','Operations','Drainage cleaning/Maintenance','Open','PENDING'),
 ('2025-06-01','2025-06-12','Operations','Drainage cleaning/Maintenance','Open','PENDING'),
 ('2025-08-01','2025-08-25','Operations','Damaged Agricultural Land','Closed','NOT_VALID'),('2025-08-01','2025-08-25','Operations','Air Quality','Open','PENDING'),
 ('2025-11-01','2025-11-05','Operations','Land Use/Compensation','Closed','VALID'),('2025-11-01','2025-11-14','Operations','Other','Closed','VALID'),
 ('2026-04-01','2026-04-06','Operations','Dust','Closed','VALID'),('2026-04-01','2026-04-20','Operations','Dust','Closed','VALID'),('2026-04-01','2026-04-23','Operations','Air Quality','open','PENDING'),
 ('2026-05-01','2026-05-04','Fier Hub','Other','Closed','VALID'),
 ('2026-06-01','2026-06-01','Operations','Dust','Closed','VALID'),('2026-06-01','2026-06-18','Operations','Dust','Closed','VALID'),
 ('2026-08-01','2026-08-18','Operations','Other','Open','PENDING')
) v(period_date, grievance_date, project_activity, category, status, validity) on p.period_date = v.period_date::date
where not exists (select 1 from public.csr_grievances g where g.reporting_period_id=p.id and g.grievance_date=v.grievance_date::date and g.project_activity=v.project_activity and g.category=v.category);
